import configparser
import os
import shutil


def task_func(config_file_path, archieve_dir='/home/user/archive'):
    if not os.path.exists(config_file_path):
        raise FileNotFoundError(f"Config file does not exist: {config_file_path}")

    config = configparser.ConfigParser()
    try:
        read_files = config.read(config_file_path)
    except Exception as exc:
        raise Exception(f"Failed to read configuration file: {exc}")

    if not read_files:
        raise Exception("Configuration file could not be read or is invalid.")

    if not config.has_section('Project'):
        raise Exception("Missing required [Project] section in configuration file.")

    if not config.has_option('Project', 'directory'):
        raise Exception("Missing required 'directory' option in [Project] section.")

    project_dir = config.get('Project', 'directory').strip()
    if not project_dir:
        raise Exception("Project directory path is empty.")

    if not os.path.exists(project_dir) or not os.path.isdir(project_dir):
        raise FileNotFoundError(f"Project directory does not exist: {project_dir}")

    try:
        os.makedirs(archieve_dir, exist_ok=True)
    except Exception as exc:
        raise Exception(f"Unable to prepare archive directory: {exc}")

    project_name = os.path.basename(os.path.normpath(project_dir))
    if not project_name:
        raise Exception("Unable to determine project directory basename.")

    archive_base = os.path.join(archieve_dir, project_name)

    try:
        archive_path = shutil.make_archive(
            base_name=archive_base,
            format='zip',
            root_dir=os.path.dirname(os.path.normpath(project_dir)),
            base_dir=project_name,
        )
    except Exception as exc:
        raise Exception(f"ZIP archive cannot be created: {exc}")

    if not os.path.exists(archive_path):
        raise Exception("ZIP archive cannot be created.")

    return True
